/// <summary>
/// Class entry point. Creates all SCRIPT prerequisite data for the EGS_API_newCustomer API test.
/// Order: CustGroup -> CustPaymModeTable -> EXU_ReceivingSystem.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    CustGroupId     custGroupId = 'TST_CstGrp';
    CustPaymMode    paymMode    = 'TST_PaymMd';
    EXU_SystemId    systemId    = 'NewSystem_TC3';

    // --- 1. CustGroup ---
    CustGroup custGroup, newCustGroup;

    select firstonly custGroup;
    select firstonly newCustGroup
        where newCustGroup.CustGroup == custGroupId;

    if (custGroup.RecId && !newCustGroup.RecId)
    {
        buf2Buf(custGroup, newCustGroup);
        newCustGroup.CustGroup = custGroupId;
        newCustGroup.Name      = 'XAPI Test Customer Group';
        newCustGroup.insert();
        info(strFmt("Inserted CustGroup: %1", custGroupId));
    }

    // --- 2. CustPaymModeTable ---
    CustPaymModeTable paymModeTable, newPaymModeTable;

    select firstonly paymModeTable;
    select firstonly newPaymModeTable
        where newPaymModeTable.PaymMode == paymMode;

    if (paymModeTable.RecId && !newPaymModeTable.RecId)
    {
        buf2Buf(paymModeTable, newPaymModeTable);
        newPaymModeTable.PaymMode = paymMode;
        newPaymModeTable.insert();
        info(strFmt("Inserted PaymMode: %1", paymMode));
    }

    // --- 3. EXU_ReceivingSystem (FK target for EXU_ReceivingSystemCust created by API) ---
    EXU_ReceivingSystem receivingSystem, newReceivingSystem;

    select firstonly receivingSystem;
    select firstonly newReceivingSystem
        where newReceivingSystem.SystemId == systemId;

    if (receivingSystem.RecId && !newReceivingSystem.RecId)
    {
        buf2Buf(receivingSystem, newReceivingSystem);
        newReceivingSystem.SystemId   = systemId;
        newReceivingSystem.SystemName = 'NewSystem TC3 (XAPI Test)';
        newReceivingSystem.insert();
        info(strFmt("Inserted EXU_ReceivingSystem: %1", systemId));
    }
}
